import{_ as a,o as t,c as d,a0 as o}from"./chunks/framework.BpJS36ta.js";const u=JSON.parse('{"title":"TODO — Rupa Language","description":"","frontmatter":{},"headers":[],"relativePath":"TODO.md","filePath":"TODO.md"}'),r={name:"TODO.md"};function i(n,e,c,s,l,m){return t(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="todo-—-rupa-language" tabindex="-1">TODO — Rupa Language <a class="header-anchor" href="#todo-—-rupa-language" aria-label="Permalink to &quot;TODO — Rupa Language&quot;">​</a></h1><blockquote><p>Status fitur: siap, dalam pengembangan, belum ada. Terakhir diperbarui: 21 September 2026</p></blockquote><hr><h2 id="ringkasan" tabindex="-1">Ringkasan <a class="header-anchor" href="#ringkasan" aria-label="Permalink to &quot;Ringkasan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kategori</th><th>Siap</th><th>Dalam Pengembangan</th><th>Belum</th></tr></thead><tbody><tr><td>Syntax &amp; Grammar</td><td>28</td><td>1</td><td>5</td></tr><tr><td>Standard Library</td><td>16</td><td>0</td><td>1</td></tr><tr><td>Module System</td><td>11</td><td>0</td><td>3</td></tr><tr><td>REPL &amp; Editor</td><td>14</td><td>1</td><td>0</td></tr><tr><td>Compiler (<code>-c</code>)</td><td>0</td><td>1</td><td>1</td></tr><tr><td>Testing</td><td>54</td><td>-</td><td>0</td></tr><tr><td>Documentation</td><td>32</td><td>0</td><td>4</td></tr></tbody></table><p>Testing: syntax <strong>54/54</strong> (<code>--test</code>), IR rewrite <strong>54/54</strong> (<code>--test-ir</code>), IR exec <strong>54/54</strong> (<code>--test-irexec</code>), execution <strong>19/19</strong> (<code>--test-exec</code> atas 13 file <code>tests/execution/</code> + 6 <code>tests/semantics/</code>), REPL <strong>31/31</strong> (<code>--test-repl</code>). Formatter: 113 file di-scan, 1 FAIL by-design (<code>tests/stress/index.rp</code> memang memicu LexerError).</p><p>Batch runner baru: <code>rupa test [kategori] [--list] [--select n]</code> dengan kategori <code>syntax</code> (default), <code>ast</code>, <code>ir</code>, <code>irexec</code>, <code>exec</code>, <code>semantics</code>, <code>repl</code>, <code>fmt</code> — plus shortcut <code>-t</code>, <code>-l</code>, <code>-p</code>, <code>-s</code> (mis. <code>rupa -ts ast 1</code>, <code>rupa -lp exec</code>). Rincian: <code>rupa help test</code>.</p><hr><h2 id="_1-syntax-grammar" tabindex="-1">1. Syntax &amp; Grammar <a class="header-anchor" href="#_1-syntax-grammar" aria-label="Permalink to &quot;1. Syntax &amp; Grammar&quot;">​</a></h2><h3 id="✅-siap" tabindex="-1">✅ Siap <a class="header-anchor" href="#✅-siap" aria-label="Permalink to &quot;✅ Siap&quot;">​</a></h3><p>Literal, Print, Assignment, Expression, String, Array, Object, If/Else, Block, Function, Return, Loop (while), Case, Call, Struct, Enum, Annotation, Update/Increment (compound <code>+=</code> dst.), Import, Export, Control Flow, Fallback, Then, Member Access, Comment — docs masing-masing di <code>docs/syntax/*.md</code> + <code>docs/grammar/*.md</code>.</p><table tabindex="0"><thead><tr><th>Fitur baru</th><th>Catatan</th></tr></thead><tbody><tr><td>Number 64-bit</td><td><code>as.number</code> = long long; <code>sizeof(number)</code> = 8; print <code>%lld</code></td></tr><tr><td>Return-type + void</td><td><code>foo(): void {}</code> — enforcement di interpreter &amp; IR</td></tr><tr><td>Class</td><td><code>Name: Type {}</code> → <code>NODE_CLASS_DECL</code>; AST <code>Class:</code>, formatter round-trip</td></tr><tr><td>Enum</td><td><code>enum Nama { MEMBER = 1 }</code> → AST member eksplisit; auto-increment</td></tr></tbody></table><h3 id="🔨-dalam-pengembangan" tabindex="-1">🔨 Dalam Pengembangan <a class="header-anchor" href="#🔨-dalam-pengembangan" aria-label="Permalink to &quot;🔨 Dalam Pengembangan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fitur</th><th>Catatan</th></tr></thead><tbody><tr><td>Async/Await</td><td><code>await</code> syntax &amp; handler blok belum stabil</td></tr><tr><td>Class (lanjutan)</td><td><code>this</code>/closure, <code>super</code>, <code>@created</code>, <code>@input</code></td></tr></tbody></table><h3 id="❌-belum-tersedia" tabindex="-1">❌ Belum Tersedia <a class="header-anchor" href="#❌-belum-tersedia" aria-label="Permalink to &quot;❌ Belum Tersedia&quot;">​</a></h3><p>For loop (C-style), Destructuring, Try/Catch, Generator/Iterator, Decorator.</p><p>Catatan: conditional-expression tertutup oleh fallback chain <code>x = primary | fallback</code> (lihat <code>docs/syntax/fallback.md</code>).</p><hr><h2 id="_2-standard-library-c" tabindex="-1">2. Standard Library (C) <a class="header-anchor" href="#_2-standard-library-c" aria-label="Permalink to &quot;2. Standard Library (C)&quot;">​</a></h2><h3 id="✅-siap-—-11-modul-native" tabindex="-1">✅ Siap — 11 modul native <a class="header-anchor" href="#✅-siap-—-11-modul-native" aria-label="Permalink to &quot;✅ Siap — 11 modul native&quot;">​</a></h3><p>os, io, json, thread, math, string (<code>stdstring</code>), http, datetime, regex, crypto, net — docs di <code>docs/modules/syntax/*.md</code> + <code>docs/modules/grammar/*.md</code>.</p><h3 id="✅-siap-—-5-rupa-packages" tabindex="-1">✅ Siap — 5 Rupa packages <a class="header-anchor" href="#✅-siap-—-5-rupa-packages" aria-label="Permalink to &quot;✅ Siap — 5 Rupa packages&quot;">​</a></h3><p>sys, fs, database, collections, strings.</p><p>Di luar hitungan: rupamemory (sizeof, blok ops contract ccpy/cmove/cset, dup family) built-in global tanpa import. pin/elpin/repin/repins/unpin <strong>dihapus</strong> — alokasi satu pintu lewat <code>new/del</code> + <code>new Contract()</code>; blok ops lama <code>setpin/movepin/copypin</code> di-rename <code>cset/cmove/ccpy</code>.</p><h3 id="❌-belum-tersedia-1" tabindex="-1">❌ Belum Tersedia <a class="header-anchor" href="#❌-belum-tersedia-1" aria-label="Permalink to &quot;❌ Belum Tersedia&quot;">​</a></h3><p>ui/view (UI rendering).</p><hr><h2 id="_3-module-system" tabindex="-1">3. Module System <a class="header-anchor" href="#_3-module-system" aria-label="Permalink to &quot;3. Module System&quot;">​</a></h2><h3 id="✅-siap-1" tabindex="-1">✅ Siap <a class="header-anchor" href="#✅-siap-1" aria-label="Permalink to &quot;✅ Siap&quot;">​</a></h3><p>Import single/local/specific/alias/wildcard, Export + alias, Namespace export block, Dotted-path export, Duplicate-export detection, Archive (<code>modules/rupa_modules.tar.gz</code>), Module cache (satu file = satu eksekusi per run, kunci canonical path), ImportError spesifik untuk semua bentuk import gagal (module tanpa export, member tidak ada, module tidak ditemukan — exit code 1), Policy <code>-&gt; { name: private }</code> multi-line, Package boundary (leaf package hanya terjangkau via rantai index-nya).</p><p><strong>Penyederhanaan bentuk import/export</strong>: hanya 4 bentuk kanonik yang tersisa (<code>import * as x</code>, <code>import x, y</code>, <code>export *</code>, <code>export x, y</code> + re-export nama). Bentuk warisan — bare import/export, member chain <code>x.y</code>, wildcard member <code>x.*</code>, entry alias, source alias — bukan bagian dari grammar (tanpa pesan migrasi; bahasa belum release). Detail di <code>docs/syntax/import.md</code> dan <code>docs/syntax/export.md</code>.</p><p>Rancangan tree export (model pohon package, policy per-edge, jalur terbuka) terkunci di dokumen internal <code>src/docs/tree_export.md</code>.</p><h3 id="❌-belum-tersedia-2" tabindex="-1">❌ Belum Tersedia <a class="header-anchor" href="#❌-belum-tersedia-2" aria-label="Permalink to &quot;❌ Belum Tersedia&quot;">​</a></h3><p>Package registry (npm-like), Version pinning, Lock file.</p><hr><h2 id="_4-formatter-repl-editor" tabindex="-1">4. Formatter &amp; REPL &amp; Editor <a class="header-anchor" href="#_4-formatter-repl-editor" aria-label="Permalink to &quot;4. Formatter &amp; REPL &amp; Editor&quot;">​</a></h2><h3 id="✅-formatter" tabindex="-1">✅ Formatter <a class="header-anchor" href="#✅-formatter" aria-label="Permalink to &quot;✅ Formatter&quot;">​</a></h3><p>Format file/stdin, spasi operator, comment, blank line, import round-trip, self-heal import, conditional assign. Arsitektur modular di <code>src/formatter/</code>.</p><h3 id="✅-repl-editor" tabindex="-1">✅ REPL &amp; Editor <a class="header-anchor" href="#✅-repl-editor" aria-label="Permalink to &quot;✅ REPL &amp; Editor&quot;">​</a></h3><p>Interactive REPL, line numbers, indentation, command, multiline input, backspace rollback, history.</p><h3 id="🔨-dalam-pengembangan-1" tabindex="-1">🔨 Dalam Pengembangan <a class="header-anchor" href="#🔨-dalam-pengembangan-1" aria-label="Permalink to &quot;🔨 Dalam Pengembangan&quot;">​</a></h3><p>Bracket pair matching (nested <code>{}</code> indent tidak akurat — <code>tests/execution/repl_struct.rp</code>).</p><hr><h2 id="_5-compiler-c" tabindex="-1">5. Compiler (<code>-c</code>) <a class="header-anchor" href="#_5-compiler-c" aria-label="Permalink to &quot;5. Compiler (`-c`)&quot;">​</a></h2><h3 id="🔨-dalam-pengembangan-2" tabindex="-1">🔨 Dalam Pengembangan <a class="header-anchor" href="#🔨-dalam-pengembangan-2" aria-label="Permalink to &quot;🔨 Dalam Pengembangan&quot;">​</a></h3><p>IR pipeline (<code>src/compiler/ir/</code>): AST → IR (<code>rewrite.c</code>) + executor (<code>execute.c</code>). <strong><code>rupa &lt;file.rp&gt;</code> kini jalan via IR</strong> (<code>runWithIR = true</code> di <code>src/prompt/runner.c</code>); interpreter tetap ada sebagai fallback (<code>--test-exec</code>/<code>--test</code>). IR → C source (transpiler) belum diimplementasi.</p><h3 id="❌-belum-tersedia-3" tabindex="-1">❌ Belum Tersedia <a class="header-anchor" href="#❌-belum-tersedia-3" aria-label="Permalink to &quot;❌ Belum Tersedia&quot;">​</a></h3><p><code>rupa -c file.rp -o binary</code> (transpile to C → native binary).</p><hr><h2 id="_6-testing" tabindex="-1">6. Testing <a class="header-anchor" href="#_6-testing" aria-label="Permalink to &quot;6. Testing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Jumlah</th><th>Status</th></tr></thead><tbody><tr><td>syntax</td><td>55</td><td>PASS</td></tr><tr><td>ir</td><td>55</td><td>PASS</td></tr><tr><td>irexec</td><td>55</td><td>PASS</td></tr><tr><td>exec</td><td>19</td><td>PASS</td></tr><tr><td>repl</td><td>18</td><td>PASS</td></tr><tr><td>fmt</td><td>1</td><td>PASS</td></tr></tbody></table><p>Suite baru: <code>number64.rp</code> (overflow 32-bit &amp; presisi 2^53), <code>void_ret.rp</code> (return-type + void + bare return), <code>class.rp</code> (class decl + construct), <code>const.rp</code> (const + re-init loop/fungsi).</p><p>Dijalankan lewat batch runner: <code>rupa test</code>, <code>rupa test --list</code>, <code>rupa test --select 1</code>, atau shortcut <code>rupa -t</code>, <code>rupa -l</code>, <code>rupa -lp ast</code>.</p><hr><h2 id="_7-documentation" tabindex="-1">7. Documentation <a class="header-anchor" href="#_7-documentation" aria-label="Permalink to &quot;7. Documentation&quot;">​</a></h2><h3 id="✅-siap-2" tabindex="-1">✅ Siap <a class="header-anchor" href="#✅-siap-2" aria-label="Permalink to &quot;✅ Siap&quot;">​</a></h3><p>Index (syntax/grammar/modules), Main, Import, Export + docs module: math, os, io, json, string, thread, http, datetime, regex, crypto, net, sys, fs, database (syntax + grammar masing-masing).</p><h3 id="❌-belum-dibuat" tabindex="-1">❌ Belum Dibuat <a class="header-anchor" href="#❌-belum-dibuat" aria-label="Permalink to &quot;❌ Belum Dibuat&quot;">​</a></h3><p><code>docs/modules/syntax/collections.md</code>, <code>docs/modules/syntax/strings.md</code>, <code>docs/syntax/namespace.md</code>, <code>docs/grammar/namespace.md</code>.</p><hr><h2 id="_8-pending-tasks" tabindex="-1">8. Pending Tasks <a class="header-anchor" href="#_8-pending-tasks" aria-label="Permalink to &quot;8. Pending Tasks&quot;">​</a></h2><h3 id="high" tabindex="-1">High <a class="header-anchor" href="#high" aria-label="Permalink to &quot;High&quot;">​</a></h3><ul><li>(kosong)</li></ul><h3 id="medium" tabindex="-1">Medium <a class="header-anchor" href="#medium" aria-label="Permalink to &quot;Medium&quot;">​</a></h3><ul><li>Class lanjutan: <code>this</code>/closure → <code>super</code> + <code>@created</code> → runner <code>rupa go</code> + <code>@input</code></li><li>Const binding ✅ (<code>const x = v</code> slot immutable, ConstError saat reassign); def/ifdef family — DITUNDA: scope-nya sub-sistem preprocessor C-style (const enum block, <code>def</code>, <code>ifdef</code>)</li><li>Design tipe: number 64-bit ✅, void ✅, const binding ✅, char/int skip, bigint defer</li><li>new Contract / new T() / del / string slot — ✅ Done; terbuka: <code>new string()</code>, interaksi const × del</li><li>new Recontract(src, n) ✅ — realloc handle GC apa pun (raw/Contract); elemSize &amp; tipe elemen diwarisi dari blok src</li><li>new Contract(count, elemsize) ✅ — calloc custom ukuran elemen eksplisit; bebas anotasi</li><li>pin family sunset ✅ — dihapus dari runtime; docs diarsipkan ke <code>docs/legacy/pin-family.md</code>, view check handle kini registry v3 (<code>memoryHandleTypeCheck</code>)</li><li>struct C-style ✅ — padding/alignment (sizeof sesuai ABI), nested struct by value + array of struct via view handle, <code>del</code> view ditolak (test: <code>tests/execution/struct_layout.rp</code>)</li><li>Formatter: rename block ops prefix <code>pin</code> — ✅ Done (<code>cset/cmove/ccpy</code>)</li></ul><h3 id="low" tabindex="-1">Low <a class="header-anchor" href="#low" aria-label="Permalink to &quot;Low&quot;">​</a></h3><ul><li>For loop (C-style)</li><li>Try/Catch error handling</li><li>UI/View module</li><li><code>-c</code> compilation (IR → C)</li></ul>',67)])])}const h=a(r,[["render",i]]);export{u as __pageData,h as default};
